mapper.insert:
insert into t_sys_comm_config(
    id, value, description, interface_name, fallback_url,
    category, status, create_time, create_by
) values (
    #{id}, #{value}, #{description}, #{interfaceName}, #{fallbackUrl},
    #{category}, #{status}, now(), #{createBy}
)

mapper.select:
select from t_sys_comm_config
and interface_name like concat('%', #{interfaceName}, '%')
and category = #{category}
and status = #{status}
and id like concat('%', #{id}, '%')
order by category, update_time desc
